import heapq


def leaderboardQueries(ops):
    score = {}
    out = []
    for t, a, b in ops:
        if t == 1:
            score[a] = score.get(a, 0) + b
        elif t == 2:
            score.pop(a, None)
        else:
            out.append(sum(heapq.nlargest(a, score.values())))
    return out
